from .models import RequestType


class RpcError(Exception):
    """RpcError"""

    def __init__(self, request, response, remote):
        message = f"{request} call at {remote} failed with {response}"
        Exception.__init__(self, message)


class NotSupportedRequestType(Exception):
    """NotSupportedRequestType"""

    def __init__(self, request_type):
        supported_request_types = [request_type.value for request_type in RequestType]
        message = f"{request_type} is not supported request type. Supported request types: {str(supported_request_types)[1:-1]}."
        Exception.__init__(self, message)
